  "$defs": {
    "version": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$",
      "not": {
        "pattern": "\\s"
      }
    },
    "epoch": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]{0,18}|1[0-7][0-9]{18}|18[0-3][0-9]{17}|184[0-3][0-9]{16}|1844[0-5][0-9]{15}|18446[0-6][0-9]{14}|184467[0-3][0-9]{13}|1844674[0-3][0-9]{12}|184467440[0-6][0-9]{10}|1844674407[0-2][0-9]{9}|18446744073[0-6][0-9]{8}|1844674407370[0-8][0-9]{6}|18446744073709[0-4][0-9]{5}|184467440737095[0-4][0-9]{4}|18446744073709550[0-9]{3}|18446744073709551[0-5][0-9]{2}|1844674407370955160[0-9]{1}|1844674407370955161[0-4]|18446744073709551615)$",
      "not": {
        "pattern": "\\s"
      }
    },
    "utc": {
      "type": "string",
      "format": "date-time",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]+)?(Z|\\+00:00)$",
      "not": {
        "pattern": "\\s"
      }
    },
    "party": {
      "type": "string",
      "enum": [
        "core",
        "client",
        "node"
      ]
    },
    "effect_state": {
      "type": "string",
      "enum": [
        "none",
        "refused",
        "failed",
        "applied",
        "cancelled",
        "unknown"
      ],
      "x-go-prefix": "Effect"
    },
    "error_code": {
      "type": "string",
      "enum": [
        "unsupported_combination",
        "capability_not_negotiated",
        "malformed",
        "stale_epoch",
        "stale_revision",
        "not_authorized",
        "out_of_scope",
        "duplicate",
        "unavailable"
      ],
      "x-go-prefix": "Error"
    },
    "protocol": {
      "type": "object",
      "properties": {
        "name": {
          "const": "client"
        },
        "version": {
          "type": "string",
          "enum": [
            "1.0",
            "1.1"
          ]
        }
      },
      "required": [
        "name",
        "version"
      ],
      "additionalProperties": false
    },
    "sender": {
      "type": "object",
      "properties": {
        "party": {
          "$ref": "#/$defs/party"
        },
        "id": {
          "type": "string"
        }
      },
      "required": [
        "party",
        "id"
      ],
      "additionalProperties": false
    },
    "receipt_ref": {
      "type": "object",
      "properties": {
        "kind": {
          "const": "receipt"
        },
        "id": {
          "type": "string"
        },
        "revision": {
          "type": "string"
        }
      },
      "required": [
        "kind",
        "id",
        "revision"
      ],
      "additionalProperties": false
    },
    "source_ref": {
      "type": "object",
      "properties": {
        "origin": {
          "type": "string"
        },
        "namespace": {
          "type": "string"
        },
        "id": {
          "type": "string"
        },
        "revision": {
          "type": "string"
        },
        "locator": {
          "type": "string"
        },
        "observed_at": {
          "$ref": "#/$defs/utc"
        },
        "observed_by": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "origin",
        "namespace",
        "id",
        "revision",
        "locator",
        "observed_at",
        "observed_by"
      ],
