    : super(value, 'mini_app_result');
  String get operation => json['operation'] as String;
  List<ProtocolMiniApp> get apps => List.unmodifiable(
    (json['apps'] as List).map(
      (v) => ProtocolMiniApp.fromJson(v as Map<String, dynamic>),
    ),
  );
  ProtocolMiniApp? get app => json['app'] == null
      ? null
      : ProtocolMiniApp.fromJson(json['app'] as Map<String, dynamic>);
  String? get url => json['url'] == null ? null : json['url'] as String;
  String? get tailnet =>
      json['tailnet'] == null ? null : json['tailnet'] as String;
  List<ProtocolMiniAppRevision>? get revisions => json['revisions'] == null
      ? null
      : List.unmodifiable(
          (json['revisions'] as List).map(
            (v) => ProtocolMiniAppRevision.fromJson(v as Map<String, dynamic>),
          ),
        );
  String? get code => json['code'] == null ? null : json['code'] as String;
}

class ProtocolLocalTask extends ProtocolObject {
  ProtocolLocalTask.fromJson(Map<String, dynamic> value)
    : super(value, 'local_task');
  String get task => json['task'] as String;
  String get text => json['text'] as String;
  String? get schema =>
      json['schema'] == null ? null : json['schema'] as String;
  String? get preference =>
      json['preference'] == null ? null : json['preference'] as String;
  ExactNumber? get images =>
      json['images'] == null ? null : ExactNumber.of(json['images']);
  List<String>? get tools => json['tools'] == null
      ? null
      : List.unmodifiable((json['tools'] as List).map((v) => v as String));
  bool? get macLocal =>
      json['mac_local'] == null ? null : json['mac_local'] as bool;
}

